import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as d,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"得物：Claude Code Spec Coding 项目实战","description":"10 天 2.5 万行代码的中后台实战：Spec 工作流、三层规范体系、MCP 工具与 AI 能力边界框架（数字归属原始来源）。","frontmatter":{"title":"得物：Claude Code Spec Coding 项目实战","description":"10 天 2.5 万行代码的中后台实战：Spec 工作流、三层规范体系、MCP 工具与 AI 能力边界框架（数字归属原始来源）。","domain":"tech","tags":["tech","case","ai-coding","spec-driven","claude-code"],"navOrder":75,"topicId":"cases-dewu-ai-implementation","layer":"appendix","status":"case","nodeType":"evidence","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/cases/dewu-ai-implementation.md","filePath":"zh/tech/appendices/cases/dewu-ai-implementation.md","lastUpdated":1791122193000}'),r={name:"zh/tech/appendices/cases/dewu-ai-implementation.md"};function n(s,t,c,i,l,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="得物-claude-code-spec-coding-项目实战" tabindex="-1">得物：Claude Code Spec Coding 项目实战 <a class="header-anchor" href="#得物-claude-code-spec-coding-项目实战" aria-label="Permalink to &quot;得物：Claude Code Spec Coding 项目实战&quot;">​</a></h1><blockquote><p>来源：<a href="https://segmentfault.com/a/1190000047648559" target="_blank" rel="noreferrer">SegmentFault - AI编程能力边界探索：基于 Claude Code 的 Spec Coding 项目实战｜得物技术</a> 替代来源：<a href="https://blog.csdn.net/u013066109/article/details/159087229" target="_blank" rel="noreferrer">CSDN - AI编程能力边界探索</a> 本文所有数字（提效、行数、调用次数）均为该来源的单案例统计，不是可外推基准。</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>一名工程师基于 Claude Code 的 <strong>Spec Coding（规格驱动编码）</strong>，10 天完成一个标准企业级中后台（表格、表单、卡片列表、数据看板），全程在「约束 + 示范 + 视觉」三层规范体系下进行。据来源统计：净增代码 25,546 行、人工指令 217 条、工具调用 2,754 次（其中文件读取 738、代码编辑 550、终端命令 662、任务进度标记 208）、整体提效 36%。</p><h2 id="spec-coding-工作流" tabindex="-1">Spec Coding 工作流 <a class="header-anchor" href="#spec-coding-工作流" aria-label="Permalink to &quot;Spec Coding 工作流&quot;">​</a></h2><p>核心思想：<strong>写代码之前，先写规格文档</strong>。通过 OpenSpec，每个功能变更经历：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Proposal → Design → Specs → Tasks</span></span></code></pre></div><p>价值：proposal 阶段先明确 why 与 how，减少返工；tasks 分组让 AI 聚焦当前步骤；每个 Change 的决策链留档可审计。</p><h2 id="开发时间线" tabindex="-1">开发时间线 <a class="header-anchor" href="#开发时间线" aria-label="Permalink to &quot;开发时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>周期</th><th>指令数</th><th>要点</th></tr></thead><tbody><tr><td>设计</td><td>—</td><td>—</td><td>Cursor + 设计规范 Rules 生成高保真 HTML 稿与 PRD</td></tr><tr><td>项目搭建</td><td>2 天</td><td>20</td><td>问答式交互，搭基础设施与项目结构</td></tr><tr><td>功能开发</td><td>4 天</td><td>89</td><td>引入 Spec Coding，约 80% 功能代码在此完成</td></tr><tr><td>打磨与部署</td><td>4 天</td><td>108</td><td>迭代、重构与生产部署排障</td></tr></tbody></table><h2 id="三层规范体系" tabindex="-1">三层规范体系 <a class="header-anchor" href="#三层规范体系" aria-label="Permalink to &quot;三层规范体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>位置</th><th>作用</th></tr></thead><tbody><tr><td>约束层</td><td><code>.claude/rules/</code></td><td>禁止什么、必须怎样（7 个规范文件：ts、命名、注释、lint、样式、页面结构、API）</td></tr><tr><td>示范层</td><td><code>.claude/code-design/</code></td><td>标准产出长什么样（pro-table、pro-form、可编辑表格、抽屉模板）</td></tr><tr><td>视觉层</td><td><code>.claude/ui-design/</code></td><td>页面应该长什么样（HTML 设计稿，AI 读取结构与样式）</td></tr></tbody></table><p>实际效果（来源统计）：205 个文件的接口函数统一 <code>fetch{Name}Api</code> 命名；<code>constants/services/hooks/components</code> 分层在新建页面中保持一致；CRUD 页面均参照 pro-table 模板。仍需人工干预的反例：AI 曾把代码写进单文件不分层、错用 <code>.less</code> 后缀。</p><h2 id="典型案例" tabindex="-1">典型案例 <a class="header-anchor" href="#典型案例" aria-label="Permalink to &quot;典型案例&quot;">​</a></h2><p><strong>AI 驱动产品设计</strong>：在 Rules 中植入「首席产品专家」persona 让 AI 先想清楚；对话式产出高保真 HTML；再以设计稿为上下文生成精确到组件行为级的 PRD——没有产品经理与 UI 设计师参与。</p><p><strong>SDD 驱动功能研发</strong>：页面功能开发人工指令 &lt; 10 条；SDD + MCP 接口文档直连完成 39 个接口联调、零返工（累计调用 21 次）；同日额外交付两个模块。</p><p><strong>SDD 驱动重构</strong>：知识问答首页重构 34 个子任务全部完成、人工干预 &lt; 5 条指令；7 个业务/公共组件解耦；<code>useChat</code> 从 20+ 方法拆为 3 个单职责 hook；<code>ChatInterface</code> 从 17 个 props 缩到 6-8 个。重构与新功能的本质差异：新功能是「从无到有」，重构是「在活体系统上动手术」。</p><p><strong>复杂排障（超出 AI 边界）</strong>：测试环境构建失败排障约 4 小时、15+ 次方案尝试、59 条指令。根因是 <code>.npmrc</code> 历史副作用、Prisma v6 境外下载沉默卡死、pnpm 跨平台 lockfile 不一致——这类跨系统历史状态问题 AI 看不到。</p><h2 id="ai-能力边界框架" tabindex="-1">AI 能力边界框架 <a class="header-anchor" href="#ai-能力边界框架" aria-label="Permalink to &quot;AI 能力边界框架&quot;">​</a></h2><p>AI 是一个「极度服从、无限耐心、但没有内部业务常识的顶级执行者」。按需求颗粒度选协作模式：</p><table tabindex="0"><thead><tr><th>颗粒度</th><th>协作模式</th><th>场景</th></tr></thead><tbody><tr><td>小</td><td>对话式</td><td>改文案、修显隐、调 CSS</td></tr><tr><td>中（标准化）</td><td>Rules / Skills</td><td>标准 CRUD、简单组件</td></tr><tr><td>中大（复杂）</td><td>OpenSpec SDD</td><td>核心重构、复杂模块</td></tr></tbody></table><p>AI 失效三种模式：<strong>规范真空</strong>（该领域无规范 → 补规范）；<strong>信息孤岛</strong>（AI 只有会话快照，看不到系统外状态 → 架构阶段提前锁定依赖）；<strong>目标模糊</strong>（把该问人的问题当执行问题 → proposal 阶段强制先写 why）。</p><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><blockquote><p>AI Coding 的本质是用结构化的规范和工作流把不确定性消除在执行之前——AI 在确定性空间里高速执行，人负责维护那个确定性空间的边界。规范是杠杆，AI 是力，Spec 工作流是支点。</p></blockquote>',24)])])}const C=e(r,[["render",n]]);export{m as __pageData,C as default};
